  goals:[["method","Un cambio de método llega primero a su tabla"],["cross","Una medida entre dominios tiene un dueño"],["team","El equipo de datos solo tiene lo compartido"],["unclaimed","Lo que nadie reclama se archiva, avisando antes"]],
